import pyomo.environ as pyo

DATA = {
    "fertilizers": ["C", "Y"],
    "nutrients": ["nitrous_oxide", "vitamin_mix"],
    "cost": {"C": 2.0, "Y": 3.0},
    "content": {
        "nitrous_oxide": {"C": 1.5, "Y": 5.0},
        "vitamin_mix": {"C": 3.0, "Y": 1.0},
    },
    "requirement": {"nitrous_oxide": 5.0, "vitamin_mix": 8.0},
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    model.I = pyo.Set(initialize=d["fertilizers"])
    model.N = pyo.Set(initialize=d["nutrients"])

    model.amount = pyo.Var(model.I, within=pyo.NonNegativeReals)

    def obj_rule(m):
        return sum(d["cost"][i] * m.amount[i] for i in m.I)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def nutrient_rule(m, n):
        return sum(d["content"][n][i] * m.amount[i] for i in m.I) >= d["requirement"][n]

    model.nutrient_req = pyo.Constraint(model.N, rule=nutrient_rule)

    return model

import pyomo.environ as pyo

DATA = {
    "ingredients": ["C", "Y"],
    "nutrients": ["nitrous", "vitamin"],
    "cost": {"C": 2.0, "Y": 3.0},
    "content": {
        "nitrous": {"C": 1.5, "Y": 5.0},
        "vitamin": {"C": 3.0, "Y": 1.0},
    },
    "requirement": {"nitrous": 5.0, "vitamin": 8.0},
}


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    model.I = pyo.Set(initialize=d["ingredients"])
    model.N = pyo.Set(initialize=d["nutrients"])

    def x_bounds(m, i):
        return (0, None)

    model.x = pyo.Var(
        model.I,
        domain=pyo.NonNegativeReals,
        bounds=x_bounds,
    )

    def cost_rule(m):
        return sum(d["cost"][i] * m.x[i] for i in m.I)

    model.obj = pyo.Objective(expr=cost_rule, sense=pyo.minimize)

    def nutrient_rule(m, n):
        return sum(d["content"][n][i] * m.x[i] for i in m.I) >= d["requirement"][n]

    model.nutrient_min = pyo.Constraint(model.N, rule=nutrient_rule)

    return model


